func allow_request(limiter: WindowLimiter, now: Int) -> Bool {
    // Check if the request is within the window
    if now - 10 < limiter.timestamps {
        return true
    }

    // Check if the number of timestamps is less than max_requests
    if limiter.timestamps.count < limiter.max_requests {
        return true
    }

    return false
}
