func is_valid_account_id(value: String) -> Bool {
    // Check if the length is exactly 8 characters
    if value.count != 8 {
        return false
    }

    // Check first 3 characters are uppercase letters
    if !value.first(3) {
        return false
    }

    // Check next 4 characters are digits
    if !value[3] {
        return false
    }

    // Check last character is a digit and valid
    if !value[4] {
        return false
    }

    // Check the last character is a digit calculated as sum of the first 4 digits modulo 10
    let firstFourDigits = value[3]
    let firstFourDigitsSum = firstFourDigits + value[4]
    let lastDigit = value[5]

    if firstFourDigitsSum % 10 != lastDigit {
        return false
    }

    return true
}
