func encode_runs(text: String) -> String {
    var result = [Character]()
    var runLength = 1

    for char in text {
        if result.count == 0 {
            result = [char]
        } else {
            runLength += 1
        }

        if runLength > 1 {
            result.append(runLength)
            result.append(char)
        } else {
            result.append(char)
        }
    }

    return result.join("")
}
